    if (s == null || s.isEmpty()) {
        return s;
    }
    int[] cnt = new int[256];
    for (char ch : s.toCharArray()) {
        cnt[ch]++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    int total = s.length();
    while (total > 0) {
        // Ascending phase: pick smallest remaining, then smallest greater than last
        int last = -1;
        while (true) {
            int next = -1;
            for (int c = last + 1; c < 256; c++) {
                if (cnt[c] > 0) {
                    next = c;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            sb.append((char) next);
            cnt[next]--;
            total--;
            last = next;
        }
        if (total == 0) {
            break;
        }
        // Descending phase: pick largest remaining, then largest smaller than last
        int lastDesc = -1;
        for (int c = 255; c >= 0; c--) {
            if (cnt[c] > 0) {
                lastDesc = c;
                break;
            }
        }
        sb.append((char) lastDesc);
        cnt[lastDesc]--;
        total--;
        while (true) {
            int prev = -1;
            for (int c = lastDesc - 1; c >= 0; c--) {
                if (cnt[c] > 0) {
                    prev = c;
                    break;
                }
            }
            if (prev == -1) {
                break;
            }
            sb.append((char) prev);
            cnt[prev]--;
            total--;
            lastDesc = prev;
        }
    }
    return sb.toString();
}

